def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

X, y = data(30, 4, 3)
for i in range(4):
    y[i] = 1
yr = X[:, 0] * 2.0 - X[:, 1] + 0.5 * y
Y2 = np.column_stack((yr, X[:, 2] ** 2))
sw = 1.0 + (np.arange(30) % 4).astype(float)
X10 = X[:10]; X5 = X[:5]

d = DummyClassifier(strategy="most_frequent", random_state=3).fit(X, y)
check(close(d.predict(X10), dc_most_frequent_pred), "dc mf pred"); check(close(d.predict_proba(X5), dc_most_frequent_proba), "dc mf proba")
d = DummyClassifier(strategy="prior", random_state=3).fit(X, y)
check(close(d.predict(X10), dc_prior_pred), "dc prior pred"); check(close(d.predict_proba(X5), dc_prior_proba), "dc prior proba")
d = DummyClassifier(strategy="stratified", random_state=3).fit(X, y)
check(close(d.predict(X10), dc_stratified_pred), "dc strat pred"); check(close(d.predict_proba(X5), dc_stratified_proba), "dc strat proba")
d = DummyClassifier(strategy="uniform", random_state=3).fit(X, y)
check(close(d.predict(X10), dc_uniform_pred), "dc unif pred"); check(close(d.predict_proba(X5), dc_uniform_proba), "dc unif proba")
d = DummyClassifier(strategy="constant", constant=2).fit(X, y)
check(close(d.predict(X[:3]), dc_const_pred), "dc const")
check(close(DummyClassifier().fit(X, y, sample_weight=sw).class_prior_, dc_prior_sw), "dc prior sw")
check(close(DummyRegressor().fit(X, yr).predict(X[:2]), dr_mean), "dr mean")
check(close(DummyRegressor(strategy="median").fit(X, yr).predict(X[:2]), dr_median), "dr median")
