Tq = np.array([0.0, 0.7, 2.5, 4.0, 6.3, 9.0, 10.0])
check(close(isotonic_regression(yi), iso_fn), "iso fn")
check(close(isotonic_regression(yi, increasing=False, y_min=1.0, y_max=4.0), iso_fn_dec), "iso fn dec")
check(close(isotonic_regression(yi, sample_weight=1 + np.arange(12.0) % 3), iso_fn_w), "iso fn w")
ir = IsotonicRegression().fit(xi, yi)
check(close(ir.X_thresholds_, iso_xt), "iso xt"); check(close(ir.y_thresholds_, iso_yt), "iso yt")
check(close(ir.predict(Tq), iso_pred), "iso pred")
ir2 = IsotonicRegression(increasing="auto", out_of_bounds="clip").fit(xi, -yi, sample_weight=1 + np.arange(12.0) % 3)
check(close(ir2.predict(Tq), iso2_pred), "iso2 pred"); check(ir2.increasing_ == iso2_inc, "iso2 inc")

Xq = X[:6] + 0.1
kr = KernelRidge(kernel="linear", alpha=0.5).fit(X, yr)
check(close(kr.dual_coef_, kr_lin_dual, 1e-8, 1e-10), "kr lin dual"); check(close(kr.predict(Xq), kr_lin_pred, 1e-8, 1e-10), "kr lin pred")
kr = KernelRidge(kernel="rbf", gamma=0.3).fit(X, yr)
check(close(kr.dual_coef_, kr_rbf_dual, 1e-8, 1e-10), "kr rbf dual"); check(close(kr.predict(Xq), kr_rbf_pred, 1e-8, 1e-10), "kr rbf pred")
