check(close(SkewedChi2Sampler(skewedness=2.0, n_components=6, random_state=3).fit_transform(Xp[:4]), skc), "skewed chi2")
check(close(AdditiveChi2Sampler().fit_transform(Xp[:3]), ac2), "additive chi2")
check(close(AdditiveChi2Sampler(sample_steps=3).fit_transform(Xp[:2]), ac3), "additive chi2 3")
ny = Nystroem(gamma=0.2, n_components=8, random_state=4).fit(X)
check(close(ny.component_indices_, ny_idx), "nystroem idx"); check(close(ny.transform(X[:4]), ny_tr, 1e-7, 1e-10), "nystroem tr")
ny2 = Nystroem(kernel="poly", degree=2.0, n_components=5, random_state=5).fit(X)
check(close(ny2.transform(X[:3]), nyp_tr, 1e-7, 1e-10), "nystroem poly")
check(close(PolynomialCountSketch(degree=2, n_components=8, random_state=6).fit_transform(X[:3]), pcs, 1e-9, 1e-12), "count sketch")
check(close(PolynomialCountSketch(degree=3, coef0=1.0, gamma=0.5, n_components=6, random_state=7).fit_transform(X[:3]), pcs2, 1e-9, 1e-11), "count sketch 2")

check(int(johnson_lindenstrauss_min_dim(1000, eps=0.3)) == jl, "jl")
Xw = np.hstack([X] * 25)
g = GaussianRandomProjection(n_components=5, random_state=8).fit(Xw)
check(close(g.components_[:2], grp_comp), "grp comp"); check(close(g.transform(Xw[:3]), grp_tr), "grp tr")
g2 = GaussianRandomProjection(eps=0.9, random_state=8).fit(Xw)
check(g2.n_components_ == grp_auto, "grp auto")
s = SparseRandomProjection(n_components=6, random_state=9).fit(Xw)
check(close(s.components_, srp_comp), "srp comp"); check(close(s.transform(Xw[:3]), srp_tr), "srp tr")
check(s.density_ == srp_dens, "srp density")
s1 = SparseRandomProjection(n_components=4, density=1.0, random_state=10, compute_inverse_components=True).fit(X)
check(close(s1.components_, srp1_comp), "srp1 comp"); check(close(s1.inverse_components_, srp1_inv, 1e-9, 1e-12), "srp1 inv")

